import React from 'react';
import './Header.css';
import ThemeSelector from './ThemeSelector';

function Header({ onAddContactClick, currentTheme, onThemeChange }) {
  return (
    <header className="header bg-primary text-white py-4 mb-4">
      <div className="container">
        <div className="row align-items-center">
          <div className="col">
            <h1 className="display-4 mb-0">CRM - Управление контактами</h1>
            <p className="lead mb-0">Простая система управления контактами на React и Node.js</p>
          </div>
          <div className="col-auto d-flex align-items-center gap-2">
            <ThemeSelector 
              currentTheme={currentTheme}
              onThemeChange={onThemeChange}
            />
            <button 
              className="btn btn-light btn-lg"
              onClick={onAddContactClick}
            >
              <i className="bi bi-person-plus me-2"></i>
              Добавить контакт
            </button>
          </div>
        </div>
      </div>
    </header>
  );
}

export default Header;
